#!/usr/bin/env bash
# YAIF installer: downloads (or unpacks --from) a release, installs the
# yaif command, its zsh completion and the .yaif MIME type, then offers to
# build the viewer plugins (Qt/KDE, GNOME/glycin, GTK/gdk-pixbuf) for
# whichever of those are present on this system.
#
# Also the uninstaller (--uninstall): every file and rc-file line this
# script writes is recorded in a manifest, and uninstalling only ever
# removes paths read back from that manifest -- never a directory, never
# a guessed or computed path.
#
#   curl -fsSL https://raw.githubusercontent.com/Thibault-Savenkoff/yaif/v2/install.sh | bash
#   curl -fsSL https://raw.githubusercontent.com/Thibault-Savenkoff/yaif/v2/install.sh | bash -s -- --uninstall
#
# Bash 3.2 compatible (macOS ships nothing newer): no arrays, no [[ ]].
set -eu

repo=Thibault-Savenkoff/yaif
prefix=$HOME/.local
system=0
nova_removed=0   # set once the former NOVA install has been removed
plugins=1
heic_hdr=1
deps=1
yes=0
from=
uninstall=0
version=
verbose=0
kde_thumb=0
CC=${CC:-cc}
# Set by test/install.sh to redirect system-wide (root) installs into a
# fake root instead of touching the real system directories or needing
# real sudo. Empty in a normal install.
TEST_ROOT=${YAIF_TEST_ROOT:-}
# Test-only: overrides the GitHub URLs with a local server. Empty in a
# normal install.
RELEASE_BASE=${YAIF_RELEASE_BASE:-https://github.com/$repo/releases/download}

# >>> i18n (generated by i18n/gensh.py from i18n/sh/*.tsv; do not edit) >>>
i18n_col=0
i18n_awk='BEGIN { FS = "\t"; k = ENVIRON["I18N_K"]; c = ENVIRON["I18N_C"] + 0; out = k }
c > 0 && $1 == k && $c != "" { out = $c; exit }
END { r = ""; while ((p = match(out, /%[1-6]/)) > 0) { r = r substr(out, 1, p - 1) ENVIRON["I18N_" substr(out, p + 1, 1)]; out = substr(out, p + 2) } printf "%s", r out }'

# i18n_pick: YAIF_LANG, else LC_ALL / LC_MESSAGES / LANG (UTF-8 only: the text is UTF-8); C, POSIX, en: English
i18n_pick() {
  local l=${YAIF_LANG:-}
  if [ -z "$l" ]; then
    l=${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}
    case $l in *[Uu][Tt][Ff]-8* | *[Uu][Tt][Ff]8*) ;; *) return 0 ;; esac
  fi
  l=${l%%.*}; l=${l%%@*}
  case $l in
    zh_TW* | zh_HK* | zh_MO* | zh_Hant*) i18n_col=15 ;;
    zh*) i18n_col=14 ;;
    fr|fr_*) i18n_col=2 ;;
    es|es_*) i18n_col=3 ;;
    de|de_*) i18n_col=4 ;;
    it|it_*) i18n_col=5 ;;
    pt_BR) i18n_col=6 ;;
    pt|pt_*) i18n_col=7 ;;
    nl|nl_*) i18n_col=8 ;;
    ru|ru_*) i18n_col=9 ;;
    pl|pl_*) i18n_col=10 ;;
    tr|tr_*) i18n_col=11 ;;
    ja|ja_*) i18n_col=12 ;;
    ko|ko_*) i18n_col=13 ;;
    hi|hi_*) i18n_col=16 ;;
    id|id_*) i18n_col=17 ;;
    vi|vi_*) i18n_col=18 ;;
    uk|uk_*) i18n_col=19 ;;
  esac
}

# t "English text with %1..%6" [values...]: that text in the user's language (English when not translated)
t() {
  if [ "$i18n_col" -gt 0 ]; then
    i18n_data | I18N_K=$1 I18N_C=$i18n_col I18N_1=${2-} I18N_2=${3-} I18N_3=${4-} I18N_4=${5-} I18N_5=${6-} I18N_6=${7-} awk "$i18n_awk"
  else
    I18N_K=$1 I18N_C=0 I18N_1=${2-} I18N_2=${3-} I18N_3=${4-} I18N_4=${5-} I18N_5=${6-} I18N_6=${7-} awk "$i18n_awk" </dev/null
  fi
}

